const python_IMPORT_RE = /^import\s+([\w.]+(?:\s+as\s+\w+)?(?:\s*,\s*[\w.]+(?:\s+as\s+\w+)?)*)$/gm;
// ─── Export Patterns ────────────────────────────────────────────
/** def function_name( */
const FUNCTION_DEF_RE = /^def\s+(\w+)\s*\(/gm;
