const CLASS_DEF_RE = /^class\s+(\w+)/gm;
/** Top-level variable assignment: NAME = ... (UPPERCASE convention for module-level constants) */
const TOP_LEVEL_VAR_RE = /^([A-Z_][A-Z0-9_]*)\s*=/gm;
